@Test
public void testSegmentLineageBasedSegmentPreSelector() {
    ZkHelixPropertyStore<ZNRecord> propertyStore = new FakePropertyStore();
    String offlineTableName = "testTable_OFFLINE";
    ExternalView externalView = new ExternalView(offlineTableName);
    Map<String, String> onlineInstanceStateMap = Collections.singletonMap("server", ONLINE);
    Set<String> onlineSegments = new HashSet<>();
    int numOfflineSegments = 5;
    for (int i = 0; i < numOfflineSegments; i++) {
        String segmentName = "segment_" + i;
        externalView.setStateMap(segmentName, onlineInstanceStateMap);
        onlineSegments.add(segmentName);
    }
    // Initialize segment pre-selector
    SegmentLineageBasedSegmentPreSelector segmentPreSelector = new SegmentLineageBasedSegmentPreSelector(offlineTableName, propertyStore);
    // Check the case where there's no segment lineage metadata for a table
    Assert.assertEquals(segmentPreSelector.preSelect(new HashSet<>(onlineSegments)), onlineSegments);
    // Update the segment lineage
    SegmentLineage segmentLineage = new SegmentLineage(offlineTableName);
    String lineageEntryId = SegmentLineageUtils.generateLineageEntryId();
    segmentLineage.addLineageEntry(lineageEntryId, new LineageEntry(Arrays.asList("segment_0", "segment_1", "segment_2"), Arrays.asList("merged_0", "merged_1"), LineageEntryState.IN_PROGRESS, System.currentTimeMillis()));
    SegmentLineageAccessHelper.writeSegmentLineage(propertyStore, segmentLineage, -1);
    Assert.assertEquals(segmentPreSelector.preSelect(new HashSet<>(onlineSegments)), new HashSet<>(Arrays.asList("segment_0", "segment_1", "segment_2", "segment_3", "segment_4")));
    // merged_0 is added
    externalView.setStateMap("merged_0", onlineInstanceStateMap);
    onlineSegments.add("merged_0");
    Assert.assertEquals(segmentPreSelector.preSelect(new HashSet<>(onlineSegments)), new HashSet<>(Arrays.asList("segment_0", "segment_1", "segment_2", "segment_3", "segment_4")));
    // merged_1 is added
    externalView.setStateMap("merged_1", onlineInstanceStateMap);
    onlineSegments.add("merged_1");
    Assert.assertEquals(segmentPreSelector.preSelect(new HashSet<>(onlineSegments)), new HashSet<>(Arrays.asList("segment_0", "segment_1", "segment_2", "segment_3", "segment_4")));
    // Lineage entry gets updated to "COMPLETED"
    LineageEntry lineageEntry = segmentLineage.getLineageEntry(lineageEntryId);
    segmentLineage.updateLineageEntry(lineageEntryId, new LineageEntry(lineageEntry.getSegmentsFrom(), lineageEntry.getSegmentsTo(), LineageEntryState.COMPLETED, System.currentTimeMillis()));
    SegmentLineageAccessHelper.writeSegmentLineage(propertyStore, segmentLineage, -1);
    Assert.assertEquals(segmentPreSelector.preSelect(new HashSet<>(onlineSegments)), new HashSet<>(Arrays.asList("segment_3", "segment_4", "merged_0", "merged_1")));
}

@Test
public void testSegmentPrunerFactoryForPartitionPruner() {
    TableConfig tableConfig = mock(TableConfig.class);
    IndexingConfig indexingConfig = mock(IndexingConfig.class);
    when(tableConfig.getIndexingConfig()).thenReturn(indexingConfig);
    // Routing config is missing
    List<SegmentPruner> segmentPruners = SegmentPrunerFactory.getSegmentPruners(tableConfig, _propertyStore);
    assertEquals(segmentPruners.size(), 1);
    assertTrue(segmentPruners.get(0) instanceof EmptySegmentPruner);
    // Segment pruner type is not configured
    RoutingConfig routingConfig = mock(RoutingConfig.class);
    when(tableConfig.getRoutingConfig()).thenReturn(routingConfig);
    segmentPruners = SegmentPrunerFactory.getSegmentPruners(tableConfig, _propertyStore);
    assertEquals(segmentPruners.size(), 1);
    assertTrue(segmentPruners.get(0) instanceof EmptySegmentPruner);
    // Segment partition config is missing
    when(routingConfig.getSegmentPrunerTypes()).thenReturn(Collections.singletonList(RoutingConfig.PARTITION_SEGMENT_PRUNER_TYPE));
    segmentPruners = SegmentPrunerFactory.getSegmentPruners(tableConfig, _propertyStore);
    assertEquals(segmentPruners.size(), 1);
    assertTrue(segmentPruners.get(0) instanceof EmptySegmentPruner);
    // Column partition config is missing
    Map<String, ColumnPartitionConfig> columnPartitionConfigMap = new HashMap<>();
    when(indexingConfig.getSegmentPartitionConfig()).thenReturn(new SegmentPartitionConfig(columnPartitionConfigMap));
    segmentPruners = SegmentPrunerFactory.getSegmentPruners(tableConfig, _propertyStore);
    assertEquals(segmentPruners.size(), 1);
    assertTrue(segmentPruners.get(0) instanceof EmptySegmentPruner);
    // Partition-aware segment pruner should be returned
    columnPartitionConfigMap.put(PARTITION_COLUMN, new ColumnPartitionConfig("Modulo", 5));
    segmentPruners = SegmentPrunerFactory.getSegmentPruners(tableConfig, _propertyStore);
    assertEquals(segmentPruners.size(), 2);
    assertTrue(segmentPruners.get(0) instanceof EmptySegmentPruner);
    assertTrue(segmentPruners.get(1) instanceof PartitionSegmentPruner);
    // Do not allow multiple partition columns
    columnPartitionConfigMap.put("anotherPartitionColumn", new ColumnPartitionConfig("Modulo", 5));
    segmentPruners = SegmentPrunerFactory.getSegmentPruners(tableConfig, _propertyStore);
    assertEquals(segmentPruners.size(), 1);
    assertTrue(segmentPruners.get(0) instanceof EmptySegmentPruner);
    // Should be backward-compatible with legacy config
    columnPartitionConfigMap.remove("anotherPartitionColumn");
    when(routingConfig.getSegmentPrunerTypes()).thenReturn(null);
    segmentPruners = SegmentPrunerFactory.getSegmentPruners(tableConfig, _propertyStore);
    assertEquals(segmentPruners.size(), 1);
    assertTrue(segmentPruners.get(0) instanceof EmptySegmentPruner);
    when(tableConfig.getTableType()).thenReturn(TableType.OFFLINE);
    when(routingConfig.getRoutingTableBuilderName()).thenReturn(SegmentPrunerFactory.LEGACY_PARTITION_AWARE_OFFLINE_ROUTING);
    segmentPruners = SegmentPrunerFactory.getSegmentPruners(tableConfig, _propertyStore);
    assertEquals(segmentPruners.size(), 2);
    assertTrue(segmentPruners.get(0) instanceof EmptySegmentPruner);
    assertTrue(segmentPruners.get(1) instanceof PartitionSegmentPruner);
    when(tableConfig.getTableType()).thenReturn(TableType.REALTIME);
    when(routingConfig.getRoutingTableBuilderName()).thenReturn(SegmentPrunerFactory.LEGACY_PARTITION_AWARE_REALTIME_ROUTING);
    segmentPruners = SegmentPrunerFactory.getSegmentPruners(tableConfig, _propertyStore);
    assertEquals(segmentPruners.size(), 2);
    assertTrue(segmentPruners.get(0) instanceof EmptySegmentPruner);
    assertTrue(segmentPruners.get(1) instanceof PartitionSegmentPruner);
}

