    preparedStatement.setString(1, "foo");
    preparedStatement.setInt(2, 20);
    preparedStatement.setDouble(3, 98.1);
    preparedStatement.setLong(4, 123456789L);
    preparedStatement.setBoolean(5, true);
    preparedStatement.setFloat(6, 1.4f);
    preparedStatement.executeQuery();
    String lastExecutedQuery = _dummyPinotClientTransport.getLastQuery();
    Assert.assertEquals(lastExecutedQuery.substring(0, lastExecutedQuery.indexOf("LIMIT")).trim(), "SELECT * FROM dummy WHERE name = 'foo' and age = 20 and score = 98.1 and ts = 123456789 and eligible = 'true' and sub_score = 1.4");
    preparedStatement.clearParameters();
    preparedStatement.setString(1, "");
    preparedStatement.setInt(2, 0);
    preparedStatement.setDouble(3, 0.0);
    preparedStatement.setLong(4, 0);
    preparedStatement.setBoolean(5, false);
    preparedStatement.setFloat(6, 0);
    preparedStatement.executeQuery();
    lastExecutedQuery = _dummyPinotClientTransport.getLastQuery();
    Assert.assertEquals(lastExecutedQuery.substring(0, lastExecutedQuery.indexOf("LIMIT")).trim(), "SELECT * FROM dummy WHERE name = '' and age = 0 and score = 0.0 and ts = 0 and eligible = 'false' and sub_score = 0.0");
