    try {
        CalciteSqlParser.compileToPinotQuery("SELECT OrderID, Quantity,\n" + "CASE\n" + "    WHEN sum(Quantity) > 30 THEN 'The quantity is greater than 30'\n" + "    WHEN sum(Quantity) = 30 THEN 'The quantity is 30'\n" + "    ELSE 'The quantity is under 30'\n" + "END AS QuantityText\n" + "FROM OrderDetails");
