    Assert.assertEquals(putMethod.getStatusCode(), 400);
    schema.setSchemaName("differentSchemaName");
    putMethod = ControllerTestUtils.sendMultipartPutRequest(ControllerTestUtils.getControllerRequestURLBuilder().forSchemaUpdate(schemaName), schema.toSingleLineJsonString());
    Assert.assertEquals(putMethod.getStatusCode(), 400);
