@Test
public void testCompleteSegmentOperations() throws Exception {
    ZKOperator zkOperator = new ZKOperator(ControllerTestUtils.getHelixResourceManager(), mock(ControllerConf.class), mock(ControllerMetrics.class));
    SegmentMetadata segmentMetadata = mock(SegmentMetadata.class);
    when(segmentMetadata.getName()).thenReturn(SEGMENT_NAME);
    when(segmentMetadata.getCrc()).thenReturn("12345");
    when(segmentMetadata.getIndexCreationTime()).thenReturn(123L);
    HttpHeaders httpHeaders = mock(HttpHeaders.class);
    zkOperator.completeSegmentOperations(TABLE_NAME_WITH_TYPE, segmentMetadata, null, null, false, httpHeaders, "downloadUrl", false, "crypter");
    OfflineSegmentZKMetadata segmentZKMetadata = ControllerTestUtils.getHelixResourceManager().getOfflineSegmentZKMetadata(TABLE_NAME, SEGMENT_NAME);
    assertEquals(segmentZKMetadata.getCrc(), 12345L);
    assertEquals(segmentZKMetadata.getCreationTime(), 123L);
    long pushTime = segmentZKMetadata.getPushTime();
    assertTrue(pushTime > 0);
    assertEquals(segmentZKMetadata.getRefreshTime(), Long.MIN_VALUE);
    assertEquals(segmentZKMetadata.getDownloadUrl(), "downloadUrl");
    assertEquals(segmentZKMetadata.getCrypterName(), "crypter");
    // Refresh the segment with unmatched IF_MATCH field
    when(httpHeaders.getHeaderString(HttpHeaders.IF_MATCH)).thenReturn("123");
    try {
        zkOperator.completeSegmentOperations(TABLE_NAME_WITH_TYPE, segmentMetadata, null, null, false, httpHeaders, "otherDownloadUrl", false, null);
        fail();
    } catch (Exception e) {
        // Expected
    }
    // Refresh the segment with the same segment (same CRC) with matched IF_MATCH field but different creation time,
    // downloadURL and crypter
    when(httpHeaders.getHeaderString(HttpHeaders.IF_MATCH)).thenReturn("12345");
    when(segmentMetadata.getIndexCreationTime()).thenReturn(456L);
    zkOperator.completeSegmentOperations(TABLE_NAME_WITH_TYPE, segmentMetadata, null, null, false, httpHeaders, "otherDownloadUrl", false, "otherCrypter");
    segmentZKMetadata = ControllerTestUtils.getHelixResourceManager().getOfflineSegmentZKMetadata(TABLE_NAME, SEGMENT_NAME);
    assertEquals(segmentZKMetadata.getCrc(), 12345L);
    // Push time should not change
    assertEquals(segmentZKMetadata.getPushTime(), pushTime);
    // Creation time and refresh time should change
    assertEquals(segmentZKMetadata.getCreationTime(), 456L);
    long refreshTime = segmentZKMetadata.getRefreshTime();
    assertTrue(refreshTime > 0);
    // DownloadURL and crypter should not unchanged
    assertEquals(segmentZKMetadata.getDownloadUrl(), "downloadUrl");
    assertEquals(segmentZKMetadata.getCrypterName(), "crypter");
    // Refresh the segment with a different segment (different CRC)
    when(segmentMetadata.getCrc()).thenReturn("23456");
    when(segmentMetadata.getIndexCreationTime()).thenReturn(789L);
    // Add a tiny sleep to guarantee that refresh time is different from the previous round
    // 1 second delay to avoid "org.apache.helix.HelixException: Specified EXTERNALVIEW operatorTestTable_OFFLINE is
    // not found!" exception from being thrown sporadically.
    Thread.sleep(1000L);
    zkOperator.completeSegmentOperations(TABLE_NAME_WITH_TYPE, segmentMetadata, null, null, false, httpHeaders, "otherDownloadUrl", false, "otherCrypter");
    segmentZKMetadata = ControllerTestUtils.getHelixResourceManager().getOfflineSegmentZKMetadata(TABLE_NAME, SEGMENT_NAME);
    assertEquals(segmentZKMetadata.getCrc(), 23456L);
    // Push time should not change
    assertEquals(segmentZKMetadata.getPushTime(), pushTime);
    // Creation time, refresh time, downloadUrl and crypter should change
    assertEquals(segmentZKMetadata.getCreationTime(), 789L);
    assertTrue(segmentZKMetadata.getRefreshTime() > refreshTime);
    assertEquals(segmentZKMetadata.getDownloadUrl(), "otherDownloadUrl");
    assertEquals(segmentZKMetadata.getCrypterName(), "otherCrypter");
}

/**
 * When config contains: 1. Both deprecated config and the corresponding new config. 2. All new
 * configurations are valid. 3. Some deprecated configurations are invalid, then new configs
 * override deprecated configs (invalid deprecated configs do not throw exceptions when
 * corresponding valid new configs are supplied as well)
 */
@Test
public void validNewConfigOverridesCorrespondingValidOrInvalidOldConfigOnRead() {
    //setup
    Map<String, Object> controllerConfig = new HashMap<>();
    int durationInSeconds = getRandomDurationInSeconds();
    DEPRECATED_CONFIGS.forEach(config -> controllerConfig.put(config, durationInSeconds));
    //put some invalid deprecated configs
    controllerConfig.put(DEPRECATED_RETENTION_MANAGER_FREQUENCY_IN_SECONDS, getRandomString());
    controllerConfig.put(DEPRECATED_SEGMENT_LEVEL_VALIDATION_INTERVAL_IN_SECONDS, getRandomString());
    //override all deprecated configs with valid new configs
    String period = getRandomPeriodInMinutes();
    NEW_CONFIGS.forEach(config -> controllerConfig.put(config, period));
    ControllerConf conf = new ControllerConf(controllerConfig);
    //execution and assertion
    assertOnDurations(conf, TimeUnit.SECONDS.convert(TimeUtils.convertPeriodToMillis(period), TimeUnit.MILLISECONDS), controllerConfig);
}

