@Test
public void testPinotTaskManagerSchedulerWithUpdate() throws Exception {
    Map<String, Object> properties = getDefaultControllerConfiguration();
    properties.put(ControllerConf.ControllerPeriodicTasksConf.PINOT_TASK_MANAGER_SCHEDULER_ENABLED, true);
    startController(properties);
    addFakeBrokerInstancesToAutoJoinHelixCluster(1, true);
    addFakeServerInstancesToAutoJoinHelixCluster(1, true);
    Schema schema = new Schema.SchemaBuilder().setSchemaName(RAW_TABLE_NAME).addSingleValueDimension("myMap", FieldSpec.DataType.STRING).addSingleValueDimension("myMapStr", FieldSpec.DataType.STRING).addSingleValueDimension("complexMapStr", FieldSpec.DataType.STRING).build();
    addSchema(schema);
    PinotTaskManager taskManager = _controllerStarter.getTaskManager();
    Scheduler scheduler = taskManager.getScheduler();
    Assert.assertNotNull(scheduler);
    // 1. Add Table
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setTaskConfig(new TableTaskConfig(ImmutableMap.of("SegmentGenerationAndPushTask", ImmutableMap.of("schedule", "0 */10 * ? * * *")))).build();
    addTableConfig(tableConfig);
    Thread.sleep(2000);
    List<String> jobGroupNames = scheduler.getJobGroupNames();
    Assert.assertEquals(jobGroupNames.size(), 1);
    for (String group : jobGroupNames) {
        Set<JobKey> jobKeys = scheduler.getJobKeys(GroupMatcher.groupEquals(group));
        for (JobKey jobKey : jobKeys) {
            JobDetail jobDetail = scheduler.getJobDetail(jobKey);
            Assert.assertEquals(jobDetail.getJobClass(), CronJobScheduleJob.class);
            Assert.assertEquals(jobDetail.getKey().getName(), RAW_TABLE_NAME + "_OFFLINE");
            Assert.assertEquals(jobDetail.getKey().getGroup(), MinionConstants.SegmentGenerationAndPushTask.TASK_TYPE);
            Assert.assertEquals(jobDetail.getJobDataMap().get("PinotTaskManager"), taskManager);
            Assert.assertEquals(jobDetail.getJobDataMap().get("LeadControllerManager"), _controllerStarter.getLeadControllerManager());
            List<? extends Trigger> triggersOfJob = scheduler.getTriggersOfJob(jobKey);
            Assert.assertEquals(triggersOfJob.size(), 1);
            for (Trigger trigger : triggersOfJob) {
                Assert.assertTrue(trigger instanceof CronTrigger);
                Assert.assertEquals(((CronTrigger) trigger).getCronExpression(), "0 */10 * ? * * *");
            }
        }
    }
    // 2. Update table to new schedule
    tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(RAW_TABLE_NAME).setTaskConfig(new TableTaskConfig(ImmutableMap.of("SegmentGenerationAndPushTask", ImmutableMap.of("schedule", "0 */20 * ? * * *")))).build();
    updateTableConfig(tableConfig);
    Thread.sleep(2000);
    jobGroupNames = scheduler.getJobGroupNames();
    Assert.assertEquals(jobGroupNames.size(), 1);
    for (String group : jobGroupNames) {
        Set<JobKey> jobKeys = scheduler.getJobKeys(GroupMatcher.groupEquals(group));
        for (JobKey jobKey : jobKeys) {
            JobDetail jobDetail = scheduler.getJobDetail(jobKey);
            Assert.assertEquals(jobDetail.getJobClass(), CronJobScheduleJob.class);
            Assert.assertEquals(jobDetail.getKey().getName(), RAW_TABLE_NAME + "_OFFLINE");
            Assert.assertEquals(jobDetail.getKey().getGroup(), MinionConstants.SegmentGenerationAndPushTask.TASK_TYPE);
            Assert.assertEquals(jobDetail.getJobDataMap().get("PinotTaskManager"), taskManager);
            Assert.assertEquals(jobDetail.getJobDataMap().get("LeadControllerManager"), _controllerStarter.getLeadControllerManager());
            List<? extends Trigger> triggersOfJob = scheduler.getTriggersOfJob(jobKey);
            Assert.assertEquals(triggersOfJob.size(), 1);
            for (Trigger trigger : triggersOfJob) {
                Assert.assertTrue(trigger instanceof CronTrigger);
                Assert.assertEquals(((CronTrigger) trigger).getCronExpression(), "0 */20 * ? * * *");
            }
        }
    }
    // 3. Drop table
    dropOfflineTable(RAW_TABLE_NAME);
    jobGroupNames = scheduler.getJobGroupNames();
    Assert.assertTrue(jobGroupNames.isEmpty());
    stopController();
}

