    // And we ask S3 to discard because it was ahead.
    params = new Request.Params().withInstanceId(s3).withStreamPartitionMsgOffset(s3Offset.toString()).withSegmentName(segmentNameStr).withReason(SegmentCompletionProtocol.REASON_TIME_LIMIT);
    response = segmentCompletionMgr.segmentConsumed(params);
    Assert.assertEquals(response.getStatus(), ControllerResponseStatus.DISCARD);
}

