@Test
public void testTableCache() throws Exception {
    TableCache tableCache = new TableCache(ControllerTestUtils.getPropertyStore(), true);
    assertNull(tableCache.getActualTableName(TABLE_NAME));
    assertNull(tableCache.getColumnNameMap(TABLE_NAME));
    assertNull(tableCache.getTableConfig(OFFLINE_TABLE_NAME));
    assertNull(tableCache.getSchema(TABLE_NAME));
    // Add a table config
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(TABLE_NAME).build();
    ControllerTestUtils.getHelixResourceManager().addTable(tableConfig);
    // Wait for at most 10 seconds for the callback to add the table config to the cache
    TestUtils.waitForCondition(aVoid -> tableCache.getTableConfig(OFFLINE_TABLE_NAME) != null, 10_000L, "Failed to add the table config to the cache");
    assertEquals(tableCache.getActualTableName(MANGLED_TABLE_NAME), TABLE_NAME);
    assertEquals(tableCache.getActualTableName(MANGLED_OFFLINE_TABLE_NAME), OFFLINE_TABLE_NAME);
    assertNull(tableCache.getActualTableName(REALTIME_TABLE_NAME));
    assertEquals(tableCache.getTableConfig(OFFLINE_TABLE_NAME), tableConfig);
    assertNull(tableCache.getColumnNameMap(TABLE_NAME));
    assertNull(tableCache.getSchema(TABLE_NAME));
    // Update the table config
    tableConfig.getIndexingConfig().setCreateInvertedIndexDuringSegmentGeneration(true);
    ControllerTestUtils.getHelixResourceManager().updateTableConfig(tableConfig);
    // Wait for at most 10 seconds for the callback to update the table config in the cache
    // NOTE: Table config should never be null during the transitioning
    TestUtils.waitForCondition(aVoid -> Preconditions.checkNotNull(tableCache.getTableConfig(OFFLINE_TABLE_NAME)).equals(tableConfig), 10_000L, "Failed to update the table config in the cache");
    assertEquals(tableCache.getActualTableName(MANGLED_TABLE_NAME), TABLE_NAME);
    assertEquals(tableCache.getActualTableName(MANGLED_OFFLINE_TABLE_NAME), OFFLINE_TABLE_NAME);
    assertNull(tableCache.getActualTableName(REALTIME_TABLE_NAME));
    assertNull(tableCache.getColumnNameMap(TABLE_NAME));
    assertNull(tableCache.getSchema(TABLE_NAME));
    // Remove the table config
    ControllerTestUtils.getHelixResourceManager().deleteOfflineTable(TABLE_NAME);
    // Wait for at most 10 seconds for the callback to remove the table config from the cache
    TestUtils.waitForCondition(aVoid -> tableCache.getTableConfig(OFFLINE_TABLE_NAME) == null, 10_000L, "Failed to remove the table config from the cache");
    assertNull(tableCache.getActualTableName(TABLE_NAME));
    assertNull(tableCache.getColumnNameMap(TABLE_NAME));
    assertNull(tableCache.getSchema(TABLE_NAME));
    // Add a schema
    Schema schema = new Schema.SchemaBuilder().setSchemaName(TABLE_NAME).addSingleValueDimension("testColumn", DataType.INT).build();
    ControllerTestUtils.getHelixResourceManager().addSchema(schema, false);
    // Wait for at most 10 seconds for the callback to add the schema to the cache
    TestUtils.waitForCondition(aVoid -> tableCache.getSchema(TABLE_NAME) != null, 10_000L, "Failed to add the schema to the cache");
    assertEquals(tableCache.getColumnNameMap(TABLE_NAME), Collections.singletonMap("testcolumn", "testColumn"));
    assertEquals(tableCache.getSchema(TABLE_NAME), schema);
    // Case-insensitive table name are handled based on the table config instead of the schema
    assertNull(tableCache.getActualTableName(TABLE_NAME));
    assertNull(tableCache.getTableConfig(OFFLINE_TABLE_NAME));
    // Update the schema
    schema.addField(new DimensionFieldSpec("newColumn", DataType.LONG, true));
    ControllerTestUtils.getHelixResourceManager().updateSchema(schema, false);
    // Wait for at most 10 seconds for the callback to update the schema in the cache
    // NOTE: schema should never be null during the transitioning
    TestUtils.waitForCondition(aVoid -> Preconditions.checkNotNull(tableCache.getSchema(TABLE_NAME)).equals(schema), 10_000L, "Failed to update the schema in the cache");
    Map<String, String> expectedColumnMap = new HashMap<>();
    expectedColumnMap.put("testcolumn", "testColumn");
    expectedColumnMap.put("newcolumn", "newColumn");
    assertEquals(tableCache.getColumnNameMap(TABLE_NAME), expectedColumnMap);
    // Case-insensitive table name are handled based on the table config instead of the schema
    assertNull(tableCache.getActualTableName(TABLE_NAME));
    assertNull(tableCache.getTableConfig(OFFLINE_TABLE_NAME));
    // Remove the schema
    ControllerTestUtils.getHelixResourceManager().deleteSchema(schema);
    // Wait for at most 10 seconds for the callback to remove the schema from the cache
    TestUtils.waitForCondition(aVoid -> tableCache.getSchema(TABLE_NAME) == null, 10_000L, "Failed to remove the schema from the cache");
    assertNull(tableCache.getActualTableName(TABLE_NAME));
    assertNull(tableCache.getColumnNameMap(TABLE_NAME));
    assertNull(tableCache.getSchema(TABLE_NAME));
}

@Test
public void testLeadControllerManager() {
    LeadControllerManager leadControllerManager = new LeadControllerManager(HELIX_CONTROLLER_INSTANCE_ID, _helixManager, _controllerMetrics);
    String tableName = "leadControllerTestTable";
    int expectedPartitionIndex = LeadControllerUtils.getPartitionIdForTable(tableName);
    String partitionName = LeadControllerUtils.generatePartitionName(expectedPartitionIndex);
    becomeHelixLeader(false);
    leadControllerManager.onHelixControllerChange();
    // When there's no resource config change nor helix controller change, leadControllerManager should return false.
    Assert.assertFalse(leadControllerManager.isLeaderForTable(tableName));
    enableResourceConfig(true);
    leadControllerManager.onResourceConfigChange();
    // Even resource config is enabled, leadControllerManager should return false because no index is cached yet.
    Assert.assertFalse(leadControllerManager.isLeaderForTable(tableName));
    Assert.assertTrue(LeadControllerUtils.isLeadControllerResourceEnabled(_helixManager));
    // After the target partition index is cached, leadControllerManager should return true.
    leadControllerManager.addPartitionLeader(partitionName);
    Assert.assertTrue(leadControllerManager.isLeaderForTable(tableName));
    // When the target partition index is removed, leadControllerManager should return false.
    leadControllerManager.removePartitionLeader(partitionName);
    Assert.assertFalse(leadControllerManager.isLeaderForTable(tableName));
    // When resource config is set to false, the cache should be disabled, even if the target partition index is in the cache.
    // The leader depends on whether the current controller is helix leader.
    enableResourceConfig(false);
    leadControllerManager.onResourceConfigChange();
    Assert.assertFalse(LeadControllerUtils.isLeadControllerResourceEnabled(_helixManager));
    Assert.assertFalse(leadControllerManager.isLeaderForTable(tableName));
    leadControllerManager.addPartitionLeader(partitionName);
    Assert.assertFalse(leadControllerManager.isLeaderForTable(tableName));
    // When the current controller becomes helix leader and resource is disabled, leadControllerManager should return true.
    becomeHelixLeader(true);
    leadControllerManager.onHelixControllerChange();
    Assert.assertTrue(leadControllerManager.isLeaderForTable(tableName));
}

