    // When ThreadCpuTimeMeasurement is disabled, value of threadCpuTimeNs is 0.
    Assert.assertEquals(newDataTable.getMetadata().get(MetadataKey.THREAD_CPU_TIME_NS.getName()), String.valueOf(0));
    // Enable ThreadCpuTimeMeasurement, serialize/de-serialize data table again.
    ThreadTimer.setThreadCpuTimeMeasurementEnabled(true);
    newDataTable = DataTableFactory.getDataTable(dataTable.toBytes());
    // When ThreadCpuTimeMeasurement is enabled, value of threadCpuTimeNs is not 0.
    Assert.assertNotEquals(newDataTable.getMetadata().get(MetadataKey.THREAD_CPU_TIME_NS.getName()), String.valueOf(0));
}

@Test
public void testDataTableMetadataBytesLayout() throws IOException {
    DataSchema.ColumnDataType[] columnDataTypes = DataSchema.ColumnDataType.values();
    int numColumns = columnDataTypes.length;
    String[] columnNames = new String[numColumns];
    for (int i = 0; i < numColumns; i++) {
        columnNames[i] = columnDataTypes[i].name();
    }
    DataSchema dataSchema = new DataSchema(columnNames, columnDataTypes);
    DataTableBuilder dataTableBuilder = new DataTableBuilder(dataSchema);
    fillDataTableWithRandomData(dataTableBuilder, columnDataTypes, numColumns);
    DataTable dataTable = dataTableBuilder.build();
    for (String key : EXPECTED_METADATA.keySet()) {
        dataTable.getMetadata().put(key, EXPECTED_METADATA.get(key));
    }
    ByteBuffer byteBuffer = ByteBuffer.wrap(dataTable.toBytes());
    int version = byteBuffer.getInt();
    Assert.assertEquals(version, DataTableBuilder.VERSION_3);
    // numOfRows
    byteBuffer.getInt();
    // numOfColumns
    byteBuffer.getInt();
    // exceptionsStart
    byteBuffer.getInt();
    // exceptionsLength
    byteBuffer.getInt();
    // dictionaryMapStart
    byteBuffer.getInt();
    // dictionaryMapLength
    byteBuffer.getInt();
    // dataSchemaStart
    byteBuffer.getInt();
    // dataSchemaLength
    byteBuffer.getInt();
    // fixedSizeDataStart
    byteBuffer.getInt();
    // fixedSizeDataLength
    byteBuffer.getInt();
    int variableSizeDataStart = byteBuffer.getInt();
    int variableSizeDataLength = byteBuffer.getInt();
    int metadataStart = variableSizeDataStart + variableSizeDataLength;
    byteBuffer.position(metadataStart);
    int metadataLength = byteBuffer.getInt();
    byte[] metadataBytes = new byte[metadataLength];
    byteBuffer.get(metadataBytes);
    try (ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(metadataBytes);
        DataInputStream dataInputStream = new DataInputStream(byteArrayInputStream)) {
        int numEntries = dataInputStream.readInt();
        // DataTable V3 serialization logic will add an extra THREAD_CPU_TIME_NS KV pair into metadata
        Assert.assertEquals(numEntries, EXPECTED_METADATA.size() + 1);
        for (int i = 0; i < numEntries; i++) {
            int keyOrdinal = dataInputStream.readInt();
            DataTable.MetadataKey key = MetadataKey.getByOrdinal(keyOrdinal);
            Assert.assertNotEquals(key, null);
            if (key.getValueType() == DataTable.MetadataValueType.INT) {
                byte[] actualBytes = new byte[Integer.BYTES];
                dataInputStream.read(actualBytes);
                Assert.assertEquals(actualBytes, Ints.toByteArray(Integer.parseInt(EXPECTED_METADATA.get(key.getName()))));
            } else if (key.getValueType() == DataTable.MetadataValueType.LONG) {
                byte[] actualBytes = new byte[Long.BYTES];
                dataInputStream.read(actualBytes);
                // Ignore the THREAD_CPU_TIME_NS key since it's added during data serialization.
                if (key != MetadataKey.THREAD_CPU_TIME_NS) {
                    Assert.assertEquals(actualBytes, Longs.toByteArray(Long.parseLong(EXPECTED_METADATA.get(key.getName()))));
                }
            } else {
                int valueLength = dataInputStream.readInt();
                byte[] actualBytes = new byte[valueLength];
                dataInputStream.read(actualBytes);
                Assert.assertEquals(actualBytes, StringUtil.encodeUtf8((EXPECTED_METADATA.get(key.getName()))));
            }
        }
    }
}

@Test
public void testBuildEmptyDataTable() throws IOException {
    // Selection
    QueryContext queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT * FROM testTable WHERE foo = 'bar'");
    DataTable dataTable = DataTableUtils.buildEmptyDataTable(queryContext);
    DataSchema dataSchema = dataTable.getDataSchema();
    assertEquals(dataSchema.getColumnNames(), new String[] { "*" });
    assertEquals(dataSchema.getColumnDataTypes(), new ColumnDataType[] { ColumnDataType.STRING });
    assertEquals(dataTable.getNumberOfRows(), 0);
    // Aggregation
    queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT COUNT(*), SUM(a), MAX(b) FROM testTable WHERE foo = 'bar'");
    dataTable = DataTableUtils.buildEmptyDataTable(queryContext);
    dataSchema = dataTable.getDataSchema();
    assertEquals(dataSchema.getColumnNames(), new String[] { "count_star", "sum_a", "max_b" });
    assertEquals(dataSchema.getColumnDataTypes(), new ColumnDataType[] { ColumnDataType.LONG, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
    assertEquals(dataTable.getNumberOfRows(), 1);
    assertEquals(dataTable.getLong(0, 0), 0L);
    assertEquals(dataTable.getDouble(0, 1), 0.0);
    assertEquals(dataTable.getDouble(0, 2), Double.NEGATIVE_INFINITY);
    // PQL group-by
    queryContext = QueryContextConverterUtils.getQueryContextFromPQL("SELECT COUNT(*), SUM(a), MAX(b) FROM testTable WHERE foo = 'bar' GROUP BY c, d");
    dataTable = DataTableUtils.buildEmptyDataTable(queryContext);
    dataSchema = dataTable.getDataSchema();
    assertEquals(dataSchema.getColumnNames(), new String[] { "functionName", "GroupByResultMap" });
    assertEquals(dataSchema.getColumnDataTypes(), new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.OBJECT });
    assertEquals(dataTable.getNumberOfRows(), 3);
    assertEquals(dataTable.getString(0, 0), "count_star");
    assertEquals(dataTable.getObject(0, 1), Collections.emptyMap());
    assertEquals(dataTable.getString(1, 0), "sum_a");
    assertEquals(dataTable.getObject(1, 1), Collections.emptyMap());
    assertEquals(dataTable.getString(2, 0), "max_b");
    assertEquals(dataTable.getObject(2, 1), Collections.emptyMap());
    // SQL group-by
    queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT c, d, COUNT(*), SUM(a), MAX(b) FROM testTable WHERE foo = 'bar' GROUP BY c, d OPTION(groupByMode=sql)");
    dataTable = DataTableUtils.buildEmptyDataTable(queryContext);
    dataSchema = dataTable.getDataSchema();
    assertEquals(dataSchema.getColumnNames(), new String[] { "c", "d", "count(*)", "sum(a)", "max(b)" });
    assertEquals(dataSchema.getColumnDataTypes(), new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.STRING, ColumnDataType.LONG, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
    assertEquals(dataTable.getNumberOfRows(), 0);
    // Distinct
    queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT DISTINCT a, b FROM testTable WHERE foo = 'bar'");
    dataTable = DataTableUtils.buildEmptyDataTable(queryContext);
    dataSchema = dataTable.getDataSchema();
    assertEquals(dataSchema.getColumnNames(), new String[] { "distinct_a:b" });
    assertEquals(dataSchema.getColumnDataTypes(), new ColumnDataType[] { ColumnDataType.OBJECT });
    assertEquals(dataTable.getNumberOfRows(), 1);
    Object firstObject = dataTable.getObject(0, 0);
    assertTrue(firstObject instanceof DistinctTable);
    DistinctTable distinctTable = (DistinctTable) firstObject;
    assertEquals(distinctTable.size(), 0);
    assertEquals(distinctTable.getDataSchema().getColumnNames(), new String[] { "a", "b" });
    assertEquals(distinctTable.getDataSchema().getColumnDataTypes(), new ColumnDataType[] { ColumnDataType.STRING, ColumnDataType.STRING });
}

