    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE floatColumn < " + Double.MAX_VALUE), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
    // Test FLOAT column greater than -Double.MAX_VALUE.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE floatColumn > " + -Double.MAX_VALUE), "Expression(type:LITERAL, literal:<Literal boolValue:true>)");
    // Test FLOAT column less than -Double.MAX_VALUE.
    Assert.assertEquals(rewrite("SELECT * FROM testTable WHERE floatColumn < " + -Double.MAX_VALUE), "Expression(type:LITERAL, literal:<Literal boolValue:false>)");
    // Test FLOAT column greater than Long.MAX_VALUE.
