@Test
public void testSelectionOrderBy() {
    List<IndexSegment> indexSegments = //
    Arrays.//
    asList(// 0
    getIndexSegment(0L, 10L, 10), // 1
    getIndexSegment(-5L, 5L, 15), // 2
    getIndexSegment(15L, 50L, 30), // 3
    getIndexSegment(5L, 15L, 20), // 4
    getIndexSegment(20L, 30L, 5), // 5
    getIndexSegment(null, null, 5), // 6
    getIndexSegment(5L, 10L, 10), // 7
    getIndexSegment(15L, 30L, 15));
    // Should keep segments: [null, null], [-5, 5], [0, 10]
    QueryContext queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT * FROM testTable ORDER BY testColumn LIMIT 5");
    List<IndexSegment> result = _segmentPruner.prune(indexSegments, queryContext);
    assertEquals(result.size(), 3);
    // [null, null], 5
    assertSame(result.get(0), indexSegments.get(5));
    // [-5, 5], 15
    assertSame(result.get(1), indexSegments.get(1));
    // [0, 10], 10
    assertSame(result.get(2), indexSegments.get(0));
    // Should keep segments: [null, null], [-5, 5], [0, 10], [5, 10], [5, 15]
    queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT * FROM testTable ORDER BY testColumn LIMIT 15, 20");
    result = _segmentPruner.prune(indexSegments, queryContext);
    assertEquals(result.size(), 5);
    // [null, null], 5
    assertSame(result.get(0), indexSegments.get(5));
    // [-5, 5], 15
    assertSame(result.get(1), indexSegments.get(1));
    // [0, 10], 10 & [5, 10], 10
    assertTrue(result.get(2) == indexSegments.get(0) || result.get(2) == indexSegments.get(6));
    assertTrue(result.get(3) == indexSegments.get(0) || result.get(3) == indexSegments.get(6));
    // [5, 15], 20
    assertSame(result.get(4), indexSegments.get(3));
    // Should keep segments: [null, null], [-5, 5], [0, 10], [5, 10], [5, 15], [15, 30], [15, 50]
    queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT * FROM testTable ORDER BY testColumn, foo LIMIT 40");
    result = _segmentPruner.prune(indexSegments, queryContext);
    assertEquals(result.size(), 7);
    // [null, null], 5
    assertSame(result.get(0), indexSegments.get(5));
    // [-5, 5], 15
    assertSame(result.get(1), indexSegments.get(1));
    // [0, 10], 10 & [5, 10], 10
    assertTrue(result.get(2) == indexSegments.get(0) || result.get(2) == indexSegments.get(6));
    assertTrue(result.get(3) == indexSegments.get(0) || result.get(3) == indexSegments.get(6));
    // [5, 15], 20
    assertSame(result.get(4), indexSegments.get(3));
    // [15, 30], 15
    assertSame(result.get(5), indexSegments.get(7));
    // [15, 50], 30
    assertSame(result.get(6), indexSegments.get(2));
    // Should keep segments: [null, null], [20, 30], [15, 50], [15, 30]
    queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT * FROM testTable ORDER BY testColumn DESC LIMIT 5");
    result = _segmentPruner.prune(indexSegments, queryContext);
    assertEquals(result.size(), 4);
    // [null, null], 5
    assertSame(result.get(0), indexSegments.get(5));
    // [20, 30], 5
    assertSame(result.get(1), indexSegments.get(4));
    // [15, 50], 30 & [15, 30], 15
    assertTrue(result.get(2) == indexSegments.get(2) || result.get(2) == indexSegments.get(7));
    assertTrue(result.get(3) == indexSegments.get(2) || result.get(3) == indexSegments.get(7));
    // Should keep segments: [null, null], [20, 30], [15, 50], [15, 30]
    queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT * FROM testTable ORDER BY testColumn DESC LIMIT 5, 30");
    result = _segmentPruner.prune(indexSegments, queryContext);
    assertEquals(result.size(), 4);
    // [null, null], 5
    assertSame(result.get(0), indexSegments.get(5));
    // [20, 30], 5
    assertSame(result.get(1), indexSegments.get(4));
    // [15, 50], 30 & [15, 30], 15
    assertTrue(result.get(2) == indexSegments.get(2) || result.get(2) == indexSegments.get(7));
    assertTrue(result.get(3) == indexSegments.get(2) || result.get(3) == indexSegments.get(7));
    // Should keep segments: [null, null], [20, 30], [15, 50], [15, 30], [5, 15], [5, 10], [0, 10], [-5, 5]
    queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT * FROM testTable ORDER BY testColumn DESC, foo LIMIT 60");
    result = _segmentPruner.prune(indexSegments, queryContext);
    assertEquals(result.size(), 8);
    // [null, null], 5
    assertSame(result.get(0), indexSegments.get(5));
    // [20, 30], 5
    assertSame(result.get(1), indexSegments.get(4));
    // [15, 50], 30 & [15, 30], 15
    assertTrue(result.get(2) == indexSegments.get(2) || result.get(2) == indexSegments.get(7));
    assertTrue(result.get(3) == indexSegments.get(2) || result.get(3) == indexSegments.get(7));
    // [5, 15], 20 & [5, 10], 10
    assertTrue(result.get(4) == indexSegments.get(3) || result.get(4) == indexSegments.get(6));
    assertTrue(result.get(5) == indexSegments.get(3) || result.get(5) == indexSegments.get(6));
    // [0, 10], 10
    assertSame(result.get(6), indexSegments.get(0));
    // [-5, 5], 15
    assertSame(result.get(7), indexSegments.get(1));
}

