    assertEquals(rhs.compareTo(lhs), -1);
    SchedulerQueryContext secondRequest = createQueryRequest("groupTwo", metrics, 3000);
    rhs.addLast(secondRequest);
    assertEquals(lhs.compareTo(rhs), 1);
    assertEquals(rhs.compareTo(lhs), -1);
}

