    assertSame(IdSets.merge(_longIdSet, IdSets.emptyIdSet()), _longIdSet);
    assertSame(IdSets.merge(IdSets.emptyIdSet(), _longIdSet), _longIdSet);
    assertSame(IdSets.merge(_intBloomFilterIdSet, IdSets.emptyIdSet()), _intBloomFilterIdSet);
    assertSame(IdSets.merge(IdSets.emptyIdSet(), _intBloomFilterIdSet), _intBloomFilterIdSet);
    assertSame(IdSets.merge(_longBloomFilterIdSet, IdSets.emptyIdSet()), _longBloomFilterIdSet);
    assertSame(IdSets.merge(IdSets.emptyIdSet(), _longBloomFilterIdSet), _longBloomFilterIdSet);
    // Merge 2 IdSets of the same type
    {
        IdSet mergedIdSet = IdSets.merge(IdSets.fromBytes(_intIdSet.toBytes()), IdSets.fromBytes(_intIdSet.toBytes()));
        assertEquals(mergedIdSet, _intIdSet);
    }
    {
        IdSet mergedIdSet = IdSets.merge(IdSets.fromBytes(_longIdSet.toBytes()), IdSets.fromBytes(_longIdSet.toBytes()));
        assertEquals(mergedIdSet, _longIdSet);
    }
    {
        IdSet mergedIdSet = IdSets.merge(IdSets.fromBytes(_intBloomFilterIdSet.toBytes()), IdSets.fromBytes(_intBloomFilterIdSet.toBytes()));
        assertEquals(mergedIdSet, _intBloomFilterIdSet);
    }
    {
        IdSet mergedIdSet = IdSets.merge(IdSets.fromBytes(_longBloomFilterIdSet.toBytes()), IdSets.fromBytes(_longBloomFilterIdSet.toBytes()));
        assertEquals(mergedIdSet, _longBloomFilterIdSet);
    }
    // Merge with BloomFilterIdSet
    {
        IdSet mergedIdSet = IdSets.merge(IdSets.fromBytes(_intIdSet.toBytes()), IdSets.fromBytes(_intBloomFilterIdSet.toBytes()));
        assertEquals(mergedIdSet, _intBloomFilterIdSet);
    }
    {
        IdSet mergedIdSet = IdSets.merge(IdSets.fromBytes(_intBloomFilterIdSet.toBytes()), IdSets.fromBytes(_intIdSet.toBytes()));
        assertEquals(mergedIdSet, _intBloomFilterIdSet);
    }
    {
        IdSet mergedIdSet = IdSets.merge(IdSets.fromBytes(_longIdSet.toBytes()), IdSets.fromBytes(_longBloomFilterIdSet.toBytes()));
        assertEquals(mergedIdSet, _longBloomFilterIdSet);
    }
    {
        IdSet mergedIdSet = IdSets.merge(IdSets.fromBytes(_longBloomFilterIdSet.toBytes()), IdSets.fromBytes(_longIdSet.toBytes()));
        assertEquals(mergedIdSet, _longBloomFilterIdSet);
    }
    // Convert to BloomFilterIdSet
    {
        IdSet mergedIdSet = IdSets.merge(IdSets.fromBytes(_intIdSet.toBytes()), IdSets.fromBytes(_intIdSet.toBytes()), 1, NUM_VALUES, IdSets.DEFAULT_FPP);
        assertEquals(mergedIdSet, _intBloomFilterIdSet);
    }
    {
        IdSet mergedIdSet = IdSets.merge(IdSets.fromBytes(_longIdSet.toBytes()), IdSets.fromBytes(_longIdSet.toBytes()), 1, NUM_VALUES, IdSets.DEFAULT_FPP);
        assertEquals(mergedIdSet, _longBloomFilterIdSet);
    }
}

