@Test
public void testAggregationGroupBy() throws IOException {
    String query = "SELECT IDSET(intColumn), IDSET(longColumn), IDSET(floatColumn), IDSET(doubleColumn), IDSET(stringColumn), IDSET(bytesColumn) FROM testTable GROUP BY 1";
    // Inner segment
    {
        AggregationGroupByOperator aggregationGroupByOperator = getOperatorForPqlQuery(query);
        IntermediateResultsBlock resultsBlock = aggregationGroupByOperator.nextBlock();
        QueriesTestUtils.testInnerSegmentExecutionStatistics(aggregationGroupByOperator.getExecutionStatistics(), NUM_RECORDS, 0, 6 * NUM_RECORDS, NUM_RECORDS);
        AggregationGroupByResult aggregationGroupByResult = resultsBlock.getAggregationGroupByResult();
        assertNotNull(aggregationGroupByResult);
        Iterator<GroupKeyGenerator.GroupKey> groupKeyIterator = aggregationGroupByResult.getGroupKeyIterator();
        int groupId = groupKeyIterator.next()._groupId;
        RoaringBitmapIdSet intIdSet = (RoaringBitmapIdSet) aggregationGroupByResult.getResultForGroupId(0, groupId);
        for (int i = 0; i < NUM_RECORDS; i++) {
            assertTrue(intIdSet.contains(_values[i]));
        }
        Roaring64NavigableMapIdSet longIdSet = (Roaring64NavigableMapIdSet) aggregationGroupByResult.getResultForGroupId(1, groupId);
        for (int i = 0; i < NUM_RECORDS; i++) {
            assertTrue(longIdSet.contains(_values[i] + (long) Integer.MAX_VALUE));
        }
        BloomFilterIdSet floatIdSet = (BloomFilterIdSet) aggregationGroupByResult.getResultForGroupId(2, groupId);
        for (int i = 0; i < NUM_RECORDS; i++) {
            assertTrue(floatIdSet.contains(_values[i] + 0.5f));
        }
        BloomFilterIdSet doubleIdSet = (BloomFilterIdSet) aggregationGroupByResult.getResultForGroupId(3, groupId);
        for (int i = 0; i < NUM_RECORDS; i++) {
            assertTrue(doubleIdSet.contains(_values[i] + 0.25));
        }
        BloomFilterIdSet stringIdSet = (BloomFilterIdSet) aggregationGroupByResult.getResultForGroupId(4, groupId);
        for (int i = 0; i < NUM_RECORDS; i++) {
            assertTrue(stringIdSet.contains(Integer.toString(_values[i])));
        }
        BloomFilterIdSet bytesIdSet = (BloomFilterIdSet) aggregationGroupByResult.getResultForGroupId(5, groupId);
        for (int i = 0; i < NUM_RECORDS; i++) {
            assertTrue(bytesIdSet.contains(Integer.toString(_values[i]).getBytes()));
        }
        assertFalse(groupKeyIterator.hasNext());
    }
    // Inter segments (expect 4 * inner segment result)
    {
        BrokerResponseNative brokerResponse = getBrokerResponseForPqlQuery(query);
        Assert.assertEquals(brokerResponse.getNumDocsScanned(), 4 * NUM_RECORDS);
        Assert.assertEquals(brokerResponse.getNumEntriesScannedInFilter(), 0);
        Assert.assertEquals(brokerResponse.getNumEntriesScannedPostFilter(), 4 * 6 * NUM_RECORDS);
        Assert.assertEquals(brokerResponse.getTotalDocs(), 4 * NUM_RECORDS);
        List<AggregationResult> aggregationResults = brokerResponse.getAggregationResults();
        Assert.assertEquals(aggregationResults.size(), 6);
        for (AggregationResult aggregationResult : aggregationResults) {
            Assert.assertNull(aggregationResult.getValue());
            List<GroupByResult> groupByResults = aggregationResult.getGroupByResult();
            assertEquals(groupByResults.size(), 1);
        }
        RoaringBitmapIdSet intIdSet = (RoaringBitmapIdSet) IdSets.fromBase64String((String) aggregationResults.get(0).getGroupByResult().get(0).getValue());
        for (int i = 0; i < NUM_RECORDS; i++) {
            assertTrue(intIdSet.contains(_values[i]));
        }
        Roaring64NavigableMapIdSet longIdSet = (Roaring64NavigableMapIdSet) IdSets.fromBase64String((String) aggregationResults.get(1).getGroupByResult().get(0).getValue());
        for (int i = 0; i < NUM_RECORDS; i++) {
            assertTrue(longIdSet.contains(_values[i] + (long) Integer.MAX_VALUE));
        }
        BloomFilterIdSet floatIdSet = (BloomFilterIdSet) IdSets.fromBase64String((String) aggregationResults.get(2).getGroupByResult().get(0).getValue());
        for (int i = 0; i < NUM_RECORDS; i++) {
            assertTrue(floatIdSet.contains(_values[i] + 0.5f));
        }
        BloomFilterIdSet doubleIdSet = (BloomFilterIdSet) IdSets.fromBase64String((String) aggregationResults.get(3).getGroupByResult().get(0).getValue());
        for (int i = 0; i < NUM_RECORDS; i++) {
            assertTrue(doubleIdSet.contains(_values[i] + 0.25));
        }
        BloomFilterIdSet stringIdSet = (BloomFilterIdSet) IdSets.fromBase64String((String) aggregationResults.get(4).getGroupByResult().get(0).getValue());
        for (int i = 0; i < NUM_RECORDS; i++) {
            assertTrue(stringIdSet.contains(Integer.toString(_values[i])));
        }
        BloomFilterIdSet bytesIdSet = (BloomFilterIdSet) IdSets.fromBase64String((String) aggregationResults.get(5).getGroupByResult().get(0).getValue());
        for (int i = 0; i < NUM_RECORDS; i++) {
            assertTrue(bytesIdSet.contains(Integer.toString(_values[i]).getBytes()));
        }
    }
}

