    Assert.assertEquals(resultTable.getDataSchema().getColumnNames(), new String[] { "column1", "column3" });
    Assert.assertEquals(resultTable.getDataSchema().getColumnDataTypes(), new DataSchema.ColumnDataType[] { DataSchema.ColumnDataType.INT, DataSchema.ColumnDataType.INT });
    Assert.assertEquals(resultTable.getRows().size(), 10);
    rows = Lists.newArrayList(new Object[] { 142002934, 17891 }, new Object[] { 142002934, 17891 }, new Object[] { 142002934, 17891 }, new Object[] { 142002934, 17891 }, new Object[] { 33273941, 84046 }, new Object[] { 33273941, 84046 }, new Object[] { 33273941, 84046 }, new Object[] { 33273941, 84046 }, new Object[] { 1002250922, 177388 }, new Object[] { 1002250922, 177388 });
    Assert.assertEquals(resultTable.getDataSchema().getColumnNames(), selectionResults.getColumns().toArray());
    for (int i = 0; i < 10; i++) {
        Assert.assertEquals(selectionResults.getRows().get(i), resultTable.getRows().get(i));
        Assert.assertEquals(resultTable.getRows().get(i), rows.get(i));
    }
