        runAndAssert(query, expected);
        query = "select distinctCountThetaSketch(thetaSketchCol, '', " + "'dimName = ''gender''', 'dimValue = ''Female''', 'SET_INTERSECT($1, $2)') from " + DEFAULT_TABLE_NAME;
        runAndAssert(query, expected);
    }
    // gender = male
    {
        String query = "select distinctCountThetaSketch(thetaSketchCol) from " + DEFAULT_TABLE_NAME + " where dimName = 'gender' and dimValue = 'Male'";
        int expected = 80 + 90 + 100 + 140 + 150 + 160;
        runAndAssert(query, expected);
        query = "select distinctCountThetaSketch(thetaSketchCol, '', 'dimName = ''gender'' and dimValue = ''Male''', '$1') from " + DEFAULT_TABLE_NAME;
        runAndAssert(query, expected);
        query = "select distinctCountThetaSketch(thetaSketchCol, '', " + "'dimName = ''gender''', 'dimValue = ''Male''', 'SET_INTERSECT($1, $2)') from " + DEFAULT_TABLE_NAME;
        runAndAssert(query, expected);
    }
    // course = math
    {
        String query = "select distinctCountThetaSketch(thetaSketchCol) from " + DEFAULT_TABLE_NAME + " where dimName = 'course' AND dimValue = 'Math'";
        int expected = 50 + 80 + 110 + 140;
        runAndAssert(query, expected);
        query = "select distinctCountThetaSketch(thetaSketchCol, '', 'dimName = ''course'' and dimValue = ''Math''', '$1') from " + DEFAULT_TABLE_NAME;
        runAndAssert(query, expected);
        query = "select distinctCountThetaSketch(thetaSketchCol, '', " + "'dimName = ''course''', 'dimValue = ''Math''', 'SET_INTERSECT($1, $2)') from " + DEFAULT_TABLE_NAME;
        runAndAssert(query, expected);
    }
    // gender = female INTERSECT course = math
    {
        String query = "select distinctCountThetaSketch(thetaSketchCol, '', " + "'dimName = ''gender'' and dimValue = ''Female''', 'dimName = ''course'' and dimValue = ''Math''', " + "'SET_INTERSECT($1, $2)') from " + DEFAULT_TABLE_NAME;
        int expected = 50 + 110;
        runAndAssert(query, expected);
        query = "select distinctCountThetaSketch(thetaSketchCol, '', " + "'dimName = ''gender''', 'dimValue = ''Female''', 'dimName = ''course''', 'dimValue = ''Math''', " + "'SET_INTERSECT($1, $2, $3, $4)') from " + DEFAULT_TABLE_NAME;
        runAndAssert(query, expected);
        query = "select distinctCountThetaSketch(thetaSketchCol, '', " + "'dimName = ''gender''', 'dimValue = ''Female''', 'dimName = ''course''', 'dimValue = ''Math''', " + "'SET_INTERSECT(SET_INTERSECT($1, $2), SET_INTERSECT($3, $4))') from " + DEFAULT_TABLE_NAME;
        runAndAssert(query, expected);
    }
    // gender = male UNION course = biology
    {
        String query = "select distinctCountThetaSketch(thetaSketchCol, '', " + "'dimName = ''gender'' and dimValue = ''Male''', 'dimName = ''course'' and dimValue = ''Biology''', " + "'SET_UNION($1, $2)') from " + DEFAULT_TABLE_NAME;
        int expected = 70 + 80 + 90 + 100 + 130 + 140 + 150 + 160;
        runAndAssert(query, expected);
        query = "select distinctCountThetaSketch(thetaSketchCol, '', " + "'dimName = ''gender''', 'dimValue = ''Male''', 'dimName = ''course''', 'dimValue = ''Biology''', " + "'SET_UNION(SET_INTERSECT($1, $2), SET_INTERSECT($3, $4))') from " + DEFAULT_TABLE_NAME;
        runAndAssert(query, expected);
    }
    // group by gender
    {
