@Test
public void testGetPinotSchemaFromAvroSchemaWithFieldTypeMap() throws IOException {
    org.apache.avro.Schema avroSchema = new org.apache.avro.Schema.Parser().parse(ClassLoader.getSystemResourceAsStream(AVRO_SCHEMA));
    Map<String, FieldSpec.FieldType> fieldSpecMap = new ImmutableMap.Builder<String, FieldSpec.FieldType>().put("d1", FieldType.DIMENSION).put("d2", FieldType.DIMENSION).put("d3", FieldType.DIMENSION).put("hoursSinceEpoch", FieldType.TIME).put("m1", FieldType.METRIC).put("m2", FieldType.METRIC).build();
    Schema inferredPinotSchema = AvroUtils.getPinotSchemaFromAvroSchema(avroSchema, fieldSpecMap, TimeUnit.HOURS);
    Schema expectedSchema = new Schema.SchemaBuilder().addSingleValueDimension("d1", DataType.STRING).addSingleValueDimension("d2", DataType.LONG).addSingleValueDimension("d3", DataType.STRING).addMetric("m1", DataType.INT).addMetric("m2", DataType.INT).addTime(new TimeGranularitySpec(DataType.LONG, TimeUnit.HOURS, "hoursSinceEpoch"), null).build();
    Assert.assertEquals(expectedSchema, inferredPinotSchema);
    fieldSpecMap = new ImmutableMap.Builder<String, FieldSpec.FieldType>().put("d1", FieldType.DIMENSION).put("d2", FieldType.DIMENSION).put("d3", FieldType.DIMENSION).put("hoursSinceEpoch", FieldType.DATE_TIME).put("m1", FieldType.METRIC).put("m2", FieldType.METRIC).build();
    inferredPinotSchema = AvroUtils.getPinotSchemaFromAvroSchema(avroSchema, fieldSpecMap, TimeUnit.HOURS);
    expectedSchema = new Schema.SchemaBuilder().addSingleValueDimension("d1", DataType.STRING).addSingleValueDimension("d2", DataType.LONG).addSingleValueDimension("d3", DataType.STRING).addMetric("m1", DataType.INT).addMetric("m2", DataType.INT).addDateTime("hoursSinceEpoch", DataType.LONG, "1:HOURS:EPOCH", "1:HOURS").build();
    Assert.assertEquals(expectedSchema, inferredPinotSchema);
}

@Test
public void testGetPinotSchemaFromAvroSchemaWithComplexType() throws IOException {
    // do not unnest collect
    org.apache.avro.Schema avroSchema = new org.apache.avro.Schema.Parser().parse(ClassLoader.getSystemResourceAsStream(AVRO_NESTED_SCHEMA));
    Map<String, FieldSpec.FieldType> fieldSpecMap = new ImmutableMap.Builder<String, FieldSpec.FieldType>().put("d1", FieldType.DIMENSION).put("hoursSinceEpoch", FieldType.TIME).put("m1", FieldType.METRIC).build();
    Schema inferredPinotSchema = AvroUtils.getPinotSchemaFromAvroSchemaWithComplexTypeHandling(avroSchema, fieldSpecMap, TimeUnit.HOURS, new ArrayList<>(), ".", ComplexTypeConfig.CollectionNotUnnestedToJson.NON_PRIMITIVE);
