    Assert.assertEquals(expectedSchema, inferredPinotSchema);
    // unnest collection entries
    inferredPinotSchema = AvroUtils.getPinotSchemaFromAvroSchemaWithComplexTypeHandling(avroSchema, fieldSpecMap, TimeUnit.HOURS, Lists.newArrayList("entries"), ".", ComplexTypeConfig.CollectionNotUnnestedToJson.NON_PRIMITIVE);
    expectedSchema = new Schema.SchemaBuilder().addSingleValueDimension("d1", DataType.STRING).addMetric("m1", DataType.INT).addSingleValueDimension("tuple.streetaddress", DataType.STRING).addSingleValueDimension("tuple.city", DataType.STRING).addSingleValueDimension("entries.id", DataType.LONG).addSingleValueDimension("entries.description", DataType.STRING).addMultiValueDimension("d2", DataType.INT).addTime(new TimeGranularitySpec(DataType.LONG, TimeUnit.HOURS, "hoursSinceEpoch"), null).build();
    Assert.assertEquals(expectedSchema, inferredPinotSchema);
    // change delimiter
    inferredPinotSchema = AvroUtils.getPinotSchemaFromAvroSchemaWithComplexTypeHandling(avroSchema, fieldSpecMap, TimeUnit.HOURS, Lists.newArrayList(), "_", ComplexTypeConfig.CollectionNotUnnestedToJson.NON_PRIMITIVE);
    expectedSchema = new Schema.SchemaBuilder().addSingleValueDimension("d1", DataType.STRING).addMetric("m1", DataType.INT).addSingleValueDimension("tuple_streetaddress", DataType.STRING).addSingleValueDimension("tuple_city", DataType.STRING).addSingleValueDimension("entries", DataType.STRING).addMultiValueDimension("d2", DataType.INT).addTime(new TimeGranularitySpec(DataType.LONG, TimeUnit.HOURS, "hoursSinceEpoch"), null).build();
    Assert.assertEquals(expectedSchema, inferredPinotSchema);
    // change the handling of collection-to-json option, d2 will become string
    inferredPinotSchema = AvroUtils.getPinotSchemaFromAvroSchemaWithComplexTypeHandling(avroSchema, fieldSpecMap, TimeUnit.HOURS, Lists.newArrayList("entries"), ".", ComplexTypeConfig.CollectionNotUnnestedToJson.ALL);
