    try (BloomFilterCreator bloomFilterCreator = new OnHeapGuavaBloomFilterCreator(TEMP_DIR, columnName, cardinality, new BloomFilterConfig(BloomFilterConfig.DEFAULT_FPP, 0, false))) {
