/**
 * Unit test for {@link SegmentPartitionConfig} that tests the following:
 * <ul>
 *   <li> Conversion from/to JSON string. </li>
 *   <li> Function names, values and ranges are as expected. </li>
 * </ul>
 * @throws IOException
 */
@Test
public void testSegmentPartitionConfig() throws IOException {
    Map<String, ColumnPartitionConfig> expectedMap = new HashMap<>();
    for (int i = 0; i < 10; i++) {
        String partitionColumn = "column_" + i;
        String partitionFunction = "function_" + i;
        expectedMap.put(partitionColumn, new ColumnPartitionConfig(partitionFunction, i + 1));
    }
    SegmentPartitionConfig expectedConfig = new SegmentPartitionConfig(expectedMap);
    SegmentPartitionConfig actualConfig = JsonUtils.stringToObject(expectedConfig.toJsonString(), SegmentPartitionConfig.class);
    for (Map.Entry<String, ColumnPartitionConfig> entry : actualConfig.getColumnPartitionMap().entrySet()) {
        String partitionColumn = entry.getKey();
        ColumnPartitionConfig expectedColumnConfig = expectedMap.get(partitionColumn);
        Assert.assertNotNull(expectedColumnConfig);
        ColumnPartitionConfig actualColumnConfig = entry.getValue();
        Assert.assertEquals(actualColumnConfig.getFunctionName(), expectedColumnConfig.getFunctionName());
    }
    // Test that adding new fields does not break json de-serialization.
    String jsonStringWithNewField = "{\"columnPartitionMap\":{\"column_0\":{\"functionName\":\"function\",\"numPartitions\":10,\"newField\":\"newValue\"}}}";
    String jsonStringWithoutNewField = "{\"columnPartitionMap\":{\"column_0\":{\"functionName\":\"function\",\"numPartitions\":10}}}";
    Assert.assertEquals(jsonStringWithoutNewField, JsonUtils.stringToObject(jsonStringWithNewField, SegmentPartitionConfig.class).toJsonString());
}

@Test
public void testFixedBitMVForwardIndex() throws Exception {
    for (int numBitsPerValue = 1; numBitsPerValue <= 31; numBitsPerValue++) {
        // Generate random values
        int[][] valuesArray = new int[NUM_DOCS][];
        int totalNumValues = 0;
        int maxValue = numBitsPerValue != 31 ? 1 << numBitsPerValue : Integer.MAX_VALUE;
        for (int i = 0; i < NUM_DOCS; i++) {
            int numValues = RANDOM.nextInt(MAX_NUM_VALUES_PER_MV_ENTRY) + 1;
            int[] values = new int[numValues];
            for (int j = 0; j < numValues; j++) {
                values[j] = RANDOM.nextInt(maxValue);
            }
            valuesArray[i] = values;
            totalNumValues += numValues;
        }
        // Create the forward index
        try (FixedBitMVForwardIndexWriter writer = new FixedBitMVForwardIndexWriter(INDEX_FILE, NUM_DOCS, totalNumValues, numBitsPerValue)) {
            for (int[] values : valuesArray) {
                writer.putDictIds(values);
            }
        }
        // Read the forward index
        try (PinotDataBuffer dataBuffer = PinotDataBuffer.mapReadOnlyBigEndianFile(INDEX_FILE);
            FixedBitMVForwardIndexReader reader = new FixedBitMVForwardIndexReader(dataBuffer, NUM_DOCS, totalNumValues, numBitsPerValue);
            FixedBitMVForwardIndexReader.Context readerContext = reader.createContext()) {
            int[] valueBuffer = new int[MAX_NUM_VALUES_PER_MV_ENTRY];
            for (int i = 0; i < NUM_DOCS; i++) {
                int numValues = reader.getDictIdMV(i, valueBuffer, readerContext);
                for (int j = 0; j < numValues; j++) {
                    assertEquals(valueBuffer[j], valuesArray[i][j]);
                }
            }
        }
        FileUtils.forceDelete(INDEX_FILE);
    }
}

