@Test
public void testH3Index() throws Exception {
    int numUniqueH3Ids = 123_456;
    Map<Long, Integer> expectedCardinalities = new HashMap<>();
    String onHeapColumnName = "onHeap";
    String offHeapColumnName = "offHeap";
    int resolution = 5;
    H3IndexResolution h3IndexResolution = new H3IndexResolution(Collections.singletonList(resolution));
    try (MutableH3Index mutableH3Index = new MutableH3Index(h3IndexResolution)) {
        try (GeoSpatialIndexCreator onHeapCreator = new OnHeapH3IndexCreator(TEMP_DIR, onHeapColumnName, h3IndexResolution);
            GeoSpatialIndexCreator offHeapCreator = new OffHeapH3IndexCreator(TEMP_DIR, offHeapColumnName, h3IndexResolution)) {
            while (expectedCardinalities.size() < numUniqueH3Ids) {
                double longitude = RANDOM.nextDouble() * 360 - 180;
                double latitude = RANDOM.nextDouble() * 180 - 90;
                Point point = GeometryUtils.GEOMETRY_FACTORY.createPoint(new Coordinate(longitude, latitude));
                onHeapCreator.add(point);
                offHeapCreator.add(point);
                mutableH3Index.add(point);
                long h3Id = H3Utils.H3_CORE.geoToH3(latitude, longitude, resolution);
                expectedCardinalities.merge(h3Id, 1, Integer::sum);
            }
            onHeapCreator.seal();
            offHeapCreator.seal();
        }
        File onHeapH3IndexFile = new File(TEMP_DIR, onHeapColumnName + V1Constants.Indexes.H3_INDEX_FILE_EXTENSION);
        File offHeapH3IndexFile = new File(TEMP_DIR, offHeapColumnName + V1Constants.Indexes.H3_INDEX_FILE_EXTENSION);
        try (PinotDataBuffer onHeapDataBuffer = PinotDataBuffer.mapReadOnlyBigEndianFile(onHeapH3IndexFile);
            PinotDataBuffer offHeapDataBuffer = PinotDataBuffer.mapReadOnlyBigEndianFile(offHeapH3IndexFile);
            H3IndexReader onHeapIndexReader = new ImmutableH3IndexReader(onHeapDataBuffer);
            H3IndexReader offHeapIndexReader = new ImmutableH3IndexReader(offHeapDataBuffer)) {
            H3IndexReader[] indexReaders = new H3IndexReader[] { onHeapIndexReader, offHeapIndexReader, mutableH3Index };
            for (H3IndexReader indexReader : indexReaders) {
                Assert.assertEquals(indexReader.getH3IndexResolution().getLowestResolution(), resolution);
                for (Map.Entry<Long, Integer> entry : expectedCardinalities.entrySet()) {
                    Assert.assertEquals(indexReader.getDocIds(entry.getKey()).getCardinality(), (int) entry.getValue());
                }
            }
        }
    }
}

@Test
public void testSmallIndex() throws Exception {
    //@formatter:off
    String[] records = new String[] { "{\"name\":\"adam\",\"age\":20,\"addresses\":[{\"street\":\"street-00\",\"country\":\"us\"},{\"street\":\"street-01\",\"country\":\"us\"},{\"street\":\"street-02\",\"country\":\"ca\"}],\"skills\":[\"english\",\"programming\"]}", "{\"name\":\"bob\",\"age\":25,\"addresses\":[{\"street\":\"street-10\",\"country\":\"ca\"},{\"street\":\"street-11\",\"country\":\"us\"},{\"street\":\"street-12\",\"country\":\"in\"}],\"skills\":[]}", "{\"name\":\"charles\",\"age\":30,\"addresses\":[{\"street\":\"street-20\",\"country\":\"jp\"},{\"street\":\"street-21\",\"country\":\"kr\"},{\"street\":\"street-22\",\"country\":\"cn\"}],\"skills\":[\"japanese\",\"korean\",\"chinese\"]}", "{\"name\":\"david\",\"age\":35,\"addresses\":[{\"street\":\"street-30\",\"country\":\"ca\",\"types\":[\"home\",\"office\"]},{\"street\":\"street-31\",\"country\":\"ca\"},{\"street\":\"street-32\",\"country\":\"ca\"}],\"skills\":null}" };
    //@formatter:on
    String onHeapColumnName = "onHeap";
    try (JsonIndexCreator onHeapIndexCreator = new OnHeapJsonIndexCreator(INDEX_DIR, onHeapColumnName)) {
        for (String record : records) {
            onHeapIndexCreator.add(record);
        }
        onHeapIndexCreator.seal();
    }
    File onHeapIndexFile = new File(INDEX_DIR, onHeapColumnName + V1Constants.Indexes.JSON_INDEX_FILE_EXTENSION);
    Assert.assertTrue(onHeapIndexFile.exists());
    String offHeapColumnName = "offHeap";
    try (JsonIndexCreator offHeapIndexCreator = new OffHeapJsonIndexCreator(INDEX_DIR, offHeapColumnName)) {
        for (String record : records) {
            offHeapIndexCreator.add(record);
        }
        offHeapIndexCreator.seal();
    }
    File offHeapIndexFile = new File(INDEX_DIR, offHeapColumnName + V1Constants.Indexes.JSON_INDEX_FILE_EXTENSION);
    Assert.assertTrue(offHeapIndexFile.exists());
    try (PinotDataBuffer onHeapDataBuffer = PinotDataBuffer.mapReadOnlyBigEndianFile(onHeapIndexFile);
        PinotDataBuffer offHeapDataBuffer = PinotDataBuffer.mapReadOnlyBigEndianFile(offHeapIndexFile);
        JsonIndexReader onHeapIndexReader = new ImmutableJsonIndexReader(onHeapDataBuffer, records.length);
        JsonIndexReader offHeapIndexReader = new ImmutableJsonIndexReader(offHeapDataBuffer, records.length);
        MutableJsonIndex mutableJsonIndex = new MutableJsonIndex()) {
        for (String record : records) {
            mutableJsonIndex.add(record);
        }
        JsonIndexReader[] indexReaders = new JsonIndexReader[] { onHeapIndexReader, offHeapIndexReader, mutableJsonIndex };
        for (JsonIndexReader indexReader : indexReaders) {
            MutableRoaringBitmap matchingDocIds = getMatchingDocIds(indexReader, "name='bob'");
            Assert.assertEquals(matchingDocIds.toArray(), new int[] { 1 });
            matchingDocIds = getMatchingDocIds(indexReader, "\"addresses[*].street\" = 'street-21'");
            Assert.assertEquals(matchingDocIds.toArray(), new int[] { 2 });
            matchingDocIds = getMatchingDocIds(indexReader, "\"addresses[*].street\" NOT IN ('street-10', 'street-22')");
            Assert.assertEquals(matchingDocIds.toArray(), new int[] { 0, 3 });
            matchingDocIds = getMatchingDocIds(indexReader, "\"addresses[0].country\" IN ('ca', 'us')");
            Assert.assertEquals(matchingDocIds.toArray(), new int[] { 0, 1, 3 });
            matchingDocIds = getMatchingDocIds(indexReader, "\"addresses[*].types[1]\" = 'office'");
            Assert.assertEquals(matchingDocIds.toArray(), new int[] { 3 });
            matchingDocIds = getMatchingDocIds(indexReader, "\"addresses[0].types[0]\" = 'home'");
            Assert.assertEquals(matchingDocIds.toArray(), new int[] { 3 });
            matchingDocIds = getMatchingDocIds(indexReader, "\"addresses[1].types[*]\" = 'home'");
            Assert.assertEquals(matchingDocIds.toArray(), new int[0]);
            matchingDocIds = getMatchingDocIds(indexReader, "\"addresses[*].types[*]\" IS NULL");
            Assert.assertEquals(matchingDocIds.toArray(), new int[] { 0, 1, 2 });
            matchingDocIds = getMatchingDocIds(indexReader, "\"addresses[1].types[*]\" IS NULL");
            Assert.assertEquals(matchingDocIds.toArray(), new int[] { 0, 1, 2, 3 });
            matchingDocIds = getMatchingDocIds(indexReader, "abc IS NULL");
            Assert.assertEquals(matchingDocIds.toArray(), new int[] { 0, 1, 2, 3 });
            matchingDocIds = getMatchingDocIds(indexReader, "\"skills[*]\" IS NOT NULL");
            Assert.assertEquals(matchingDocIds.toArray(), new int[] { 0, 2 });
            matchingDocIds = getMatchingDocIds(indexReader, "\"addresses[*].country\" = 'ca' AND \"skills[*]\" IS NOT NULL");
            Assert.assertEquals(matchingDocIds.toArray(), new int[] { 0 });
            matchingDocIds = getMatchingDocIds(indexReader, "\"addresses[*].country\" = 'us' OR \"skills[*]\" IS NOT NULL");
            Assert.assertEquals(matchingDocIds.toArray(), new int[] { 0, 1, 2 });
        }
    }
}

