    String[] records = new String[numRecords];
    for (int i = 0; i < numRecords; i++) {
        records[i] = String.format("{\"name\":\"adam-%d\",\"addresses\":[{\"street\":\"us-%d\",\"country\":\"us\"},{\"street\":\"ca-%d\",\"country\":\"ca\"}]}", i, i, i);
