@Test
public void testValidateUpsertConfig() {
    Schema schema = new Schema.SchemaBuilder().setSchemaName(TABLE_NAME).addSingleValueDimension("myCol", FieldSpec.DataType.STRING).build();
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(TABLE_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL, null, null)).build();
    try {
        TableConfigUtils.validateUpsertConfig(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Upsert table is for realtime table only.");
    }
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL, null, null)).build();
    try {
        TableConfigUtils.validateUpsertConfig(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Upsert table must have primary key columns in the schema");
    }
    schema = new Schema.SchemaBuilder().setSchemaName(TABLE_NAME).addSingleValueDimension("myCol", FieldSpec.DataType.STRING).setPrimaryKeyColumns(Lists.newArrayList("myCol")).build();
    try {
        TableConfigUtils.validateUpsertConfig(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Could not find streamConfigs for REALTIME table: " + TABLE_NAME + "_REALTIME");
    }
    Map<String, String> streamConfigs = getStreamConfigs();
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL, null, null)).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validateUpsertConfig(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Upsert table must use low-level streaming consumer type");
    }
    streamConfigs.put("stream.kafka.consumer.type", "simple");
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL, null, null)).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validateUpsertConfig(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Upsert table must use strict replica-group (i.e. strictReplicaGroup) based routing");
    }
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL, null, null)).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE)).setStreamConfigs(streamConfigs).build();
    TableConfigUtils.validateUpsertConfig(tableConfig, schema);
    StarTreeIndexConfig starTreeIndexConfig = new StarTreeIndexConfig(Lists.newArrayList("myCol"), null, Collections.singletonList(new AggregationFunctionColumnPair(AggregationFunctionType.COUNT, "myCol").toColumnName()), 10);
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL, null, null)).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE)).setStarTreeIndexConfigs(Lists.newArrayList(starTreeIndexConfig)).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validateUpsertConfig(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "The upsert table cannot have star-tree index.");
    }
}

@Test
public void testValidatePartialUpsertConfig() {
    Schema schema = new Schema.SchemaBuilder().setSchemaName(TABLE_NAME).addSingleValueDimension("myCol1", FieldSpec.DataType.LONG).addSingleValueDimension("myCol2", FieldSpec.DataType.STRING).addDateTime("myTimeCol", FieldSpec.DataType.LONG, "1:DAYS:EPOCH", "1:DAYS").setPrimaryKeyColumns(Lists.newArrayList("myCol1")).build();
    Map<String, String> streamConfigs = getStreamConfigs();
    streamConfigs.put("stream.kafka.consumer.type", "simple");
    Map<String, UpsertConfig.Strategy> partialUpsertStratgies = new HashMap<>();
    partialUpsertStratgies.put("myCol1", UpsertConfig.Strategy.INCREMENT);
    TableConfig tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.PARTIAL, partialUpsertStratgies, null)).setNullHandlingEnabled(false).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE)).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validatePartialUpsertStrategies(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Null handling must be enabled for partial upsert tables");
    }
    tableConfig.getIndexingConfig().setNullHandlingEnabled(true);
    try {
        TableConfigUtils.validatePartialUpsertStrategies(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Merger cannot be applied to primary key columns");
    }
    partialUpsertStratgies.clear();
    partialUpsertStratgies.put("randomCol", UpsertConfig.Strategy.OVERWRITE);
    try {
        TableConfigUtils.validatePartialUpsertStrategies(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "Merger cannot be applied to non-existing column: randomCol");
    }
    partialUpsertStratgies.clear();
    partialUpsertStratgies.put("myCol2", UpsertConfig.Strategy.INCREMENT);
    try {
        TableConfigUtils.validatePartialUpsertStrategies(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "INCREMENT merger cannot be applied to non-numeric column: myCol2");
    }
    partialUpsertStratgies.clear();
    partialUpsertStratgies.put("myCol2", UpsertConfig.Strategy.APPEND);
    try {
        TableConfigUtils.validatePartialUpsertStrategies(tableConfig, schema);
        Assert.fail();
    } catch (IllegalStateException e) {
        Assert.assertEquals(e.getMessage(), "APPEND merger cannot be applied to single-value column: myCol2");
    }
    partialUpsertStratgies.clear();
    partialUpsertStratgies.put("myTimeCol", UpsertConfig.Strategy.INCREMENT);
    try {
        TableConfigUtils.validatePartialUpsertStrategies(tableConfig, schema);
        Assert.fail();
    } catch (Exception e) {
        Assert.assertEquals(e.getMessage(), "INCREMENT merger cannot be applied to date time column: myTimeCol");
    }
}

