public void testPinotByteBuffer() throws Exception {
    try (PinotDataBuffer buffer = PinotByteBuffer.allocateDirect(BUFFER_SIZE, ByteOrder.BIG_ENDIAN)) {
        testPinotDataBuffer(buffer);
