    try (PinotDataBuffer writeBuffer = PinotByteBuffer.mapFile(TEMP_FILE, false, FILE_OFFSET, 3 * BUFFER_SIZE, PinotDataBuffer.NATIVE_ORDER)) {
        putLongs(writeBuffer, startOffset);
        try (PinotDataBuffer readBuffer = PinotByteBuffer.loadFile(TEMP_FILE, FILE_OFFSET, 3 * BUFFER_SIZE, PinotDataBuffer.NATIVE_ORDER)) {
            testViewAndToDirectByteBuffer(readBuffer, startOffset);
        }
        try (PinotDataBuffer readBuffer = PinotByteBuffer.mapFile(TEMP_FILE, true, FILE_OFFSET, 3 * BUFFER_SIZE, PinotDataBuffer.NATIVE_ORDER)) {
