        try (PinotDataBuffer readBuffer = PinotNativeOrderLBuffer.mapFile(TEMP_FILE, true, FILE_OFFSET, 3 * BUFFER_SIZE)) {
            testViewAndToDirectByteBuffer(readBuffer, startOffset);
        }
    } finally {
        FileUtils.forceDelete(TEMP_FILE);
    }
    try (PinotDataBuffer writeBuffer = PinotByteBuffer.mapFile(TEMP_FILE, false, FILE_OFFSET, 3 * BUFFER_SIZE, PinotDataBuffer.NON_NATIVE_ORDER)) {
        putLongs(writeBuffer, startOffset);
        try (PinotDataBuffer readBuffer = PinotByteBuffer.loadFile(TEMP_FILE, FILE_OFFSET, 3 * BUFFER_SIZE, PinotDataBuffer.NON_NATIVE_ORDER)) {
            testViewAndToDirectByteBuffer(readBuffer, startOffset);
