                    Assert.assertTrue(buffer3 instanceof PinotByteBuffer);
                    testBufferStats(2, 2 * BUFFER_SIZE, 1, BUFFER_SIZE);
                }
                testBufferStats(2, 2 * BUFFER_SIZE, 0, 0);
            }
            testBufferStats(1, BUFFER_SIZE, 0, 0);
