    Schema inferredPinotSchema = JsonUtils.getPinotSchemaFromJsonFile(file, fieldSpecMap, TimeUnit.HOURS, new ArrayList<>(), ".", ComplexTypeConfig.CollectionNotUnnestedToJson.NON_PRIMITIVE);
    Schema expectedSchema = new Schema.SchemaBuilder().addSingleValueDimension("d1", FieldSpec.DataType.STRING).addMetric("m1", FieldSpec.DataType.INT).addSingleValueDimension("tuple.address.streetaddress", FieldSpec.DataType.STRING).addSingleValueDimension("tuple.address.city", FieldSpec.DataType.STRING).addSingleValueDimension("entries", FieldSpec.DataType.STRING).addMultiValueDimension("d2", FieldSpec.DataType.INT).addDateTime("hoursSinceEpoch", FieldSpec.DataType.INT, "1:HOURS:EPOCH", "1:HOURS").build();
    Assert.assertEquals(inferredPinotSchema, expectedSchema);
    // unnest collection entries
    inferredPinotSchema = JsonUtils.getPinotSchemaFromJsonFile(file, fieldSpecMap, TimeUnit.HOURS, Lists.newArrayList("entries"), ".", ComplexTypeConfig.CollectionNotUnnestedToJson.NON_PRIMITIVE);
    expectedSchema = new Schema.SchemaBuilder().addSingleValueDimension("d1", FieldSpec.DataType.STRING).addMetric("m1", FieldSpec.DataType.INT).addSingleValueDimension("tuple.address.streetaddress", FieldSpec.DataType.STRING).addSingleValueDimension("tuple.address.city", FieldSpec.DataType.STRING).addSingleValueDimension("entries.id", FieldSpec.DataType.INT).addSingleValueDimension("entries.description", FieldSpec.DataType.STRING).addMultiValueDimension("d2", FieldSpec.DataType.INT).addDateTime("hoursSinceEpoch", FieldSpec.DataType.INT, "1:HOURS:EPOCH", "1:HOURS").build();
    Assert.assertEquals(inferredPinotSchema, expectedSchema);
    // change delimiter
    inferredPinotSchema = JsonUtils.getPinotSchemaFromJsonFile(file, fieldSpecMap, TimeUnit.HOURS, Lists.newArrayList(""), "_", ComplexTypeConfig.CollectionNotUnnestedToJson.NON_PRIMITIVE);
    expectedSchema = new Schema.SchemaBuilder().addSingleValueDimension("d1", FieldSpec.DataType.STRING).addMetric("m1", FieldSpec.DataType.INT).addSingleValueDimension("tuple_address_streetaddress", FieldSpec.DataType.STRING).addSingleValueDimension("tuple_address_city", FieldSpec.DataType.STRING).addSingleValueDimension("entries", FieldSpec.DataType.STRING).addMultiValueDimension("d2", FieldSpec.DataType.INT).addDateTime("hoursSinceEpoch", FieldSpec.DataType.INT, "1:HOURS:EPOCH", "1:HOURS").build();
    Assert.assertEquals(inferredPinotSchema, expectedSchema);
    // change the handling of collection-to-json option, d2 will become string
    inferredPinotSchema = JsonUtils.getPinotSchemaFromJsonFile(file, fieldSpecMap, TimeUnit.HOURS, Lists.newArrayList("entries"), ".", ComplexTypeConfig.CollectionNotUnnestedToJson.ALL);
    expectedSchema = new Schema.SchemaBuilder().addSingleValueDimension("d1", FieldSpec.DataType.STRING).addMetric("m1", FieldSpec.DataType.INT).addSingleValueDimension("tuple.address.streetaddress", FieldSpec.DataType.STRING).addSingleValueDimension("tuple.address.city", FieldSpec.DataType.STRING).addSingleValueDimension("entries.id", FieldSpec.DataType.INT).addSingleValueDimension("entries.description", FieldSpec.DataType.STRING).addSingleValueDimension("d2", FieldSpec.DataType.STRING).addDateTime("hoursSinceEpoch", FieldSpec.DataType.INT, "1:HOURS:EPOCH", "1:HOURS").build();
    Assert.assertEquals(inferredPinotSchema, expectedSchema);
}

@Test
public void testNoDelayRetryPolicy() {
    NoDelayRetryPolicy noDelayRetryPolicy = new NoDelayRetryPolicy(MAX_NUM_ATTEMPTS);
    for (int i = 0; i < NUM_ROUNDS; i++) {
        for (int j = 0; j < MAX_NUM_ATTEMPTS; j++) {
            Assert.assertEquals(noDelayRetryPolicy.getDelayMs(j), 0);
        }
    }
}

@Test
public void testFixedDelayRetryPolicy() {
    FixedDelayRetryPolicy fixedDelayRetryPolicy = new FixedDelayRetryPolicy(MAX_NUM_ATTEMPTS, 10);
    for (int i = 0; i < NUM_ROUNDS; i++) {
        for (int j = 0; j < MAX_NUM_ATTEMPTS; j++) {
            Assert.assertEquals(fixedDelayRetryPolicy.getDelayMs(j), 10);
        }
    }
}

@Test
public void testRandomDelayRetryPolicy() {
    RandomDelayRetryPolicy randomDelayRetryPolicy = new RandomDelayRetryPolicy(MAX_NUM_ATTEMPTS, 10, 11);
    for (int i = 0; i < NUM_ROUNDS; i++) {
        for (int j = 0; j < MAX_NUM_ATTEMPTS; j++) {
            Assert.assertTrue(randomDelayRetryPolicy.getDelayMs(j) >= 10);
            Assert.assertTrue(randomDelayRetryPolicy.getDelayMs(j) < 11);
        }
    }
    randomDelayRetryPolicy = new RandomDelayRetryPolicy(MAX_NUM_ATTEMPTS, 10, 100);
    for (int i = 0; i < NUM_ROUNDS; i++) {
        for (int j = 0; j < MAX_NUM_ATTEMPTS; j++) {
            Assert.assertTrue(randomDelayRetryPolicy.getDelayMs(j) >= 10);
            Assert.assertTrue(randomDelayRetryPolicy.getDelayMs(j) < 100);
        }
    }
    randomDelayRetryPolicy = new RandomDelayRetryPolicy(MAX_NUM_ATTEMPTS, Integer.MAX_VALUE, (long) Integer.MAX_VALUE + 1);
    for (int i = 0; i < NUM_ROUNDS; i++) {
        for (int j = 0; j < MAX_NUM_ATTEMPTS; j++) {
            Assert.assertTrue(randomDelayRetryPolicy.getDelayMs(j) >= Integer.MAX_VALUE);
            Assert.assertTrue(randomDelayRetryPolicy.getDelayMs(j) < (long) Integer.MAX_VALUE + 1);
        }
    }
    randomDelayRetryPolicy = new RandomDelayRetryPolicy(MAX_NUM_ATTEMPTS, (long) Integer.MAX_VALUE + 1, (long) Integer.MAX_VALUE + 10);
    for (int i = 0; i < NUM_ROUNDS; i++) {
        for (int j = 0; j < MAX_NUM_ATTEMPTS; j++) {
            Assert.assertTrue(randomDelayRetryPolicy.getDelayMs(j) >= (long) Integer.MAX_VALUE + 1);
            Assert.assertTrue(randomDelayRetryPolicy.getDelayMs(j) < (long) Integer.MAX_VALUE + 10);
        }
    }
}

@Test
public void testExponentialBackoffRetryPolicy() {
    ExponentialBackoffRetryPolicy exponentialBackoffRetryPolicy = new ExponentialBackoffRetryPolicy(MAX_NUM_ATTEMPTS, 10, 2.0);
    for (int i = 0; i < NUM_ROUNDS; i++) {
        for (int j = 0; j < MAX_NUM_ATTEMPTS; j++) {
            long delayMs = exponentialBackoffRetryPolicy.getDelayMs(j);
            Assert.assertTrue(delayMs >= 10 * Math.pow(2.0, j));
            Assert.assertTrue(delayMs < 10 * Math.pow(2.0, j + 1));
        }
    }
}

@Test
public void testBaseRetryPolicy() throws Exception {
    RetryPolicy retryPolicy = RetryPolicies.noDelayRetryPolicy(MAX_NUM_ATTEMPTS);
    for (int i = 0; i < NUM_ROUNDS; i++) {
        retryPolicy.attempt(() -> true);
        try {
            retryPolicy.attempt(() -> false);
            Assert.fail();
        } catch (AttemptsExceededException e) {
            // Expected
        }
        try {
            retryPolicy.attempt(() -> null);
            Assert.fail();
        } catch (AttemptsExceededException e) {
            // Expected
        }
        try {
            retryPolicy.attempt(() -> {
                throw new RuntimeException();
            });
            Assert.fail();
        } catch (RetriableOperationException e) {
            // Expected
        }
    }
}

@Test
public void testIntTimeColumn() {
    TimeConverter converter = new TimeConverter(new TimeGranularitySpec(FieldSpec.DataType.INT, 5, TimeUnit.HOURS, "time"));
    // Should support conversion from all data types
    assertEquals(converter.toMillisSinceEpoch(123), 123 * TimeUnit.HOURS.toMillis(5));
    assertEquals(converter.toMillisSinceEpoch(123L), 123 * TimeUnit.HOURS.toMillis(5));
    assertEquals(converter.toMillisSinceEpoch(123f), 123 * TimeUnit.HOURS.toMillis(5));
    assertEquals(converter.toMillisSinceEpoch(123d), 123 * TimeUnit.HOURS.toMillis(5));
    assertEquals(converter.toMillisSinceEpoch("123"), 123 * TimeUnit.HOURS.toMillis(5));
    assertEquals(converter.fromMillisSinceEpoch(123 * TimeUnit.HOURS.toMillis(5)), 123);
}

